  # Rend une icône Heroicons outline en SVG inline.
  # Usage : <%= heroicon :calculator, class: "w-6 h-6" %>
  def heroicon(name, css_class: "w-6 h-6")
    path = HEROICON_PATHS.fetch(name) { raise ArgumentError, "Icône inconnue : #{name}" }

    content_tag(:svg, xmlns: "http://www.w3.org/2000/svg", fill: "none", viewBox: "0 0 24 24",
                "stroke-width": 1.5, stroke: "currentColor", class: css_class, "aria-hidden": true) do
      content_tag(:path, nil, "stroke-linecap": "round", "stroke-linejoin": "round", d: path)
    end
  end
end
